    precondition((serviceAction["ActionParameters"] as! [String:Any])["COMMAND_STRING"] as? String == "/usr/bin/open -b com.apple.calculator")
    for object in [service.info,service.document]{_ = try! PropertyListSerialization.data(fromPropertyList:object,format:.xml,options:0)}
