// Exercise the production writer with simulated firmware. Never opens a USB
// device, creates a system input event, or changes the user's configuration.
private final class SimulatedCherry: CherryHardwareAccess {
    var state: HardwareSnapshot
    var packets: [[UInt8]] = []
    var saved: [HardwareSnapshot] = []
    var readCommands: [UInt8] = []
    var checks = 0
    var reads = 0
    var failSendAt: Int?
    var heldFromCheck: Int?
    var corruptReadAt: Int?
    var backupFails = false
    var unexpectedChangeAt:Int?
    var drains: [TimeInterval] = []
    init(_ state: HardwareSnapshot) { self.state = state }
    func snapshot(includeColors: Bool) throws -> HardwareSnapshot {
        reads += 1
        var result = state
        result.keymap = try read(8,count:378,baseOffset:0)
        if !includeColors { result.colors = nil }
        if corruptReadAt == reads { result.keymap[0] ^= 1 }
        return result
    }
    func read(_ command:UInt8,count:Int,baseOffset:Int) throws -> [UInt8] {
        readCommands.append(command)
        let bytes: [UInt8]
        switch command {
        case 8: bytes=state.keymap
        case 7: bytes=Array(repeating:0,count:378) // Deliberately distinct factory table.
        case 0x14: bytes=state.macroData!
        default: throw HardwareError(message:"unexpected read")
        }
        return Array(bytes[baseOffset..<baseOffset+count])
    }
    func waitUntilKeysReleased(timeout:TimeInterval) throws {
        checks += 1
        if let heldFromCheck, checks >= heldFromCheck { throw HardwareError(message:"simulated held key") }
    }
    func backup(_ snapshot:HardwareSnapshot) throws -> URL {
        if backupFails { throw HardwareError(message:"simulated backup failure") }
        saved.append(snapshot)
        return URL(fileURLWithPath:"/tmp/cherrymac-simulated-backup.json")
    }
    func waitForMacroCompletion(seconds:TimeInterval) throws {
        drains.append(seconds);try waitUntilKeysReleased(timeout:5)
    }
    func exchange(_ packet:[UInt8]) throws -> [UInt8] {
        // Every individual write, including rollback, needs a release check.
        precondition(heldFromCheck == nil || checks < heldFromCheck!)
        precondition(checks > packets.count)
        packets.append(packet)
        let offset=Int(packet[5]) | Int(packet[6])<<8
        let end=offset+Int(packet[4]);let bytes=Array(packet[8..<8+Int(packet[4])])
        switch packet[3] {
        case 9: state.keymap.replaceSubrange(offset..<end,with:bytes)
        case 6: precondition(packet[7]==0x55);state.parameters.replaceSubrange(offset..<end,with:bytes)
        case 0x0B: state.colors!.replaceSubrange(offset..<end,with:bytes)
        case 0x15: state.macroData!.replaceSubrange(offset..<end,with:bytes)
        default: preconditionFailure("unexpected mutation")
        }
        // A lost acknowledgement may follow a successful device-side write.
        if unexpectedChangeAt==packets.count{state.parameters[9] ^= 1}
        if failSendAt == packets.count { throw HardwareError(message:"simulated lost acknowledgement") }
        try CherryPacket.validate(packet,request:packet)
        return packet
    }
}

private func runMacroPlaybackTests(){
    func rejected(_ body:() throws->Void){do{try body();preconditionFailure("expected playback rejection")}catch{}}
    let macro=KeyboardMacro(name:"A",steps:[.init(usage:4,pressed:true,delayMilliseconds:0),.init(usage:4,pressed:false,delayMilliseconds:50)])
    let modes:[MacroPlayback]=[.once,.init(mode:.count,count:2),.init(mode:.count,count:255),.init(mode:.held,count:1),.init(mode:.toggle,count:1)]
    let wire:[[UInt8]]=[[0x70,0,0],[0x71,0,2],[0x71,0,255],[0x70,0,1],[0x70,0,2]]
    for (playback,expected) in zip(modes,wire){
        precondition(try! CherryMacroCodec.binding(0,playback:playback)==expected)
        var s=HardwareSnapshot.demo();s.macroData=try! CherryMacroCodec.encode([macro]);s.keymap.replaceSubrange(306..<309,with:expected)
        let decoded=try! HardwareProfile.fromHardware(s)
        precondition(decoded.macroModes?[102]==playback && (try! decoded.resolvedMacros()).keymap==s.keymap)
        precondition(try! HardwareProfile.decode(decoded.encoded())==decoded)
        rejected{_ = try KeymapWriteAuthorization(baseline:HardwareSnapshot.demo(),keymap:s.keymap)}
    }
    for bad in [[UInt8(0x70),0,3],[0x71,0,0],[0x71,0,1],[0x70,1,0]]{rejected{_ = try CherryMacroCodec.playback(bad,macroCount:1)}}
    for value in [0,256]{rejected{_ = try CherryMacroCodec.binding(0,playback:.init(mode:.count,count:value))}}
    rejected{_ = try CherryMacroCodec.binding(0,playback:.init(mode:.held,count:2))}
    var legacy=HardwareProfile(snapshot:HardwareSnapshot.demo(),macros:[macro],macroBindings:[102:"A"])
    legacy.snapshot.keymap.replaceSubrange(306..<309,with:[0x70,0,0])
    precondition(Array((try! legacy.resolvedMacros()).keymap[306..<309])==[0x70,0,0])
    let editor=HardwareWindowController();editor.profile=try! HardwareProfile.fromHardware(HardwareSnapshot.demo())
    editor.macroName.stringValue="A";editor.macroText.string="A 按下 0\nA 松开 50";editor.stageMacro()
    editor.macroPlayback.selectItem(at:0);editor.macroRepeat.stringValue="3";editor.assignMacro()
    precondition(Array(editor.profile!.snapshot.keymap[306..<309])==[0x71,0,3])
    editor.loadSelectedAssignment();precondition(editor.macroRepeat.stringValue=="3")
    editor.macroPlayback.selectItem(at:2);editor.assignMacro();precondition(Array(editor.profile!.snapshot.keymap[306..<309])==[0x70,0,2])
    editor.actionPicker.selectItem(at:3);editor.stageKey();precondition(editor.profile!.macroModes?[102]==nil)
    print("PASS: official count/held/toggle macro bindings, legacy single-run compatibility, per-key preservation, editor staging and invalid-mode rejection (offline only; macro writes remain paused)")
}

private func runScopedKeymapTests(){
    func fails(_ block:() throws->Void){do{try block();preconditionFailure("expected key-scope rejection")}catch{}}
    let original=HardwareSnapshot.demo()
    var map=original.keymap;map.replaceSubrange(306..<309,with:[32,13,6]);map.replaceSubrange(27..<30,with:[32,0,5])
    let authorization=try! KeymapWriteAuthorization(baseline:original,keymap:map)
    precondition(authorization.changedSlots==[9,102])
    for bytes in [original.keymap,map]{for o in stride(from:0,to:378,by:54){try! authorization.validate(CherryPacket.chunk(9,offset:o,length:54,data:Array(bytes[o..<o+54])))}}
    for slot in [6,71,125]{var next=original.keymap;next.replaceSubrange(slot*3..<slot*3+3,with:[32,0,4]);fails{_ = try KeymapWriteAuthorization(baseline:original,keymap:next)}}
    var macro=original.keymap;macro.replaceSubrange(306..<309,with:[0x70,0,0]);fails{_ = try KeymapWriteAuthorization(baseline:original,keymap:macro)}
    var oldMacro=original;oldMacro.keymap=macro;fails{_ = try KeymapWriteAuthorization(baseline:oldMacro,keymap:map)}
    for record:[UInt8] in [[32,0,0],[32,0,4],[32,255,0],[48,205,0]]{var next=original.keymap;next.replaceSubrange(306..<309,with:record);_ = try! KeymapWriteAuthorization(baseline:original,keymap:next)}
    for code:UInt8 in [1,2,3,224,255]{var next=original.keymap;next.replaceSubrange(306..<309,with:[32,0,code]);fails{_ = try KeymapWriteAuthorization(baseline:original,keymap:next)}}
    fails{try authorization.validate(CherryPacket.chunk(9,offset:306,length:3,data:[32,13,6]))}
    fails{try authorization.validate(CherryPacket.chunk(0x0B,offset:0,length:54,data:Array(original.colors!.prefix(54))))}
    var mixed=original;mixed.keymap.replaceSubrange(0..<54,with:map[0..<54]);try! authorization.validateRecovery(mixed)
    mixed.keymap[12] ^= 1;fails{try authorization.validateRecovery(mixed)}
    let success=SimulatedCherry(original)
    precondition(try! success.writeKeymap(map,baseline:original,recoveryAuthorization:authorization).keymap==map)
    precondition(success.saved==[original] && success.packets.count==7 && success.packets.allSatisfy{$0[3]==9})
    for packet in success.packets{try! authorization.validate(packet)}
    let swapped=SimulatedCherry(original);swapped.state.deviceInfo[0] ^= 1
    fails{_ = try swapped.writeKeymap(map,baseline:original,recoveryAuthorization:authorization)}
    precondition(swapped.packets.isEmpty && swapped.saved.isEmpty)
    let lost=SimulatedCherry(original);lost.failSendAt=6
    fails{_ = try lost.writeKeymap(map,baseline:original,recoveryAuthorization:authorization)}
    precondition(lost.state==original && lost.packets.count==13)
    let outside=SimulatedCherry(original);outside.unexpectedChangeAt=7
    fails{_ = try outside.writeKeymap(map,baseline:original,recoveryAuthorization:authorization)}
    precondition(outside.packets.count==7 && outside.state.parameters[9] != original.parameters[9])
    let directory=FileManager.default.temporaryDirectory.appendingPathComponent("CherryMacLogTest-\(UUID().uuidString)")
    let logger=try! HardwareOperationLog(kind:"keymap",directory:directory)
    logger.trace("OUT "+String(repeating:"00",count:64));logger.trace("IN  "+String(repeating:"00",count:64));logger.record("phase","complete");try! logger.requireHealthy()
    let saved=try! JSONSerialization.jsonObject(with:Data(contentsOf:logger.url)) as! [String:Any]
    let trace=saved["trace"] as! [[String:Any]]
    precondition(saved["phase"] as? String == "complete" && trace.contains{$0["durationMs"] != nil})
    precondition(trace.last?["field"] as? String == "phase" && trace.last?["value"] as? String == "complete")
    try! FileManager.default.removeItem(at:directory);logger.record("phase","will-fail");fails{try logger.requireHealthy()}
    print("PASS: product key scope supports ordinary/chord/media/disable, preserves hidden/internal/macro bindings, rejects non-key packets, backs up and checks scope before recovery (simulated firmware)")
}

private func runHardwareMacroTests(_ fixture:HardwareSnapshot) {
