private func runHardwareWriteTests(_ fixture:HardwareSnapshot) {
    func rejected(_ block:() throws -> Void) -> String {
        do { try block();preconditionFailure("expected writer rejection") }
        catch { return error.localizedDescription }
    }
    var gate=ReleasedKeyGate()
    precondition(!gate.observe(anyKeyDown:false,now:0))
    precondition(!gate.observe(anyKeyDown:false,now:0.1))
    precondition(gate.observe(anyKeyDown:false,now:0.25))
    precondition(!gate.observe(anyKeyDown:true,now:0.3))
    precondition(!gate.observe(anyKeyDown:false,now:0.35))
    precondition(!gate.observe(anyKeyDown:false,now:0.5))
    precondition(gate.observe(anyKeyDown:false,now:0.56))

    var original=fixture
    original.keymap[9..<12]=[0x20,8,21] // A pre-existing custom mapping must survive.
    var desired=original.keymap
    desired.replaceSubrange(0..<3,with:[0x20,0,4])
    desired.replaceSubrange(306..<309,with:[0x20,13,6])
    let success=SimulatedCherry(original)
    let result=try! success.writeKeymap(desired,baseline:original)
    precondition(result.keymap==desired && result.colors==original.colors && result.parameters==original.parameters)
    precondition(success.saved==[original] && success.packets.count==7 && success.checks==8)
    precondition(success.readCommands.allSatisfy{$0==8})

    let stale=SimulatedCherry(original)
    var outdated=original;outdated.keymap[0] ^= 1
    _=rejected{try stale.writeKeymap(desired,baseline:outdated)}
    precondition(stale.packets.isEmpty && stale.saved.isEmpty)
    let noBackup=SimulatedCherry(original);noBackup.backupFails=true
    _=rejected{try noBackup.writeKeymap(desired,baseline:original)}
    precondition(noBackup.packets.isEmpty)
    let held=SimulatedCherry(original);held.heldFromCheck=1
    _=rejected{try held.writeKeymap(desired,baseline:original)}
    precondition(held.packets.isEmpty && held.state==original)

    for failureAt in [1,4,7] {
        let failing=SimulatedCherry(original);failing.failSendAt=failureAt
        let error=rejected{try failing.writeKeymap(desired,baseline:original)}
        precondition(failing.state==original && error.contains("已恢复"))
        precondition(failing.packets.count==failureAt+7)
    }
    let badRead=SimulatedCherry(original);badRead.corruptReadAt=2
    _=rejected{try badRead.writeKeymap(desired,baseline:original)}
    precondition(badRead.state==original && badRead.packets.count==14)
    let heldDuringWrite=SimulatedCherry(original);heldDuringWrite.heldFromCheck=4
    let blockedRestore=rejected{try heldDuringWrite.writeKeymap(desired,baseline:original)}
    precondition(heldDuringWrite.packets.count==2 && heldDuringWrite.state != original && blockedRestore.contains("自动恢复失败") && blockedRestore.contains("备份"))
    let unchanged=SimulatedCherry(original)
    _=try! unchanged.writeKeymap(original.keymap,baseline:original)
    precondition(unchanged.packets.isEmpty && unchanged.saved.isEmpty)

    var lights=original
    lights.colors!.replaceSubrange(306..<309,with:[0,120,255])
    lights.colors!.replaceSubrange(324..<327,with:[255,0,0])
    lights.parameters[2]=3
    let lighting=SimulatedCherry(original)
    let lit=try! lighting.writeLighting(lights,baseline:original)
    precondition(lit==lights && lighting.packets.count==3 && lighting.saved==[original])
    let lightFailure=SimulatedCherry(original);lightFailure.failSendAt=2
    _=rejected{_ = try lightFailure.writeLighting(lights,baseline:original)}
    precondition(lightFailure.state==original && lightFailure.packets.count==5)
    let heldLighting=SimulatedCherry(original);heldLighting.heldFromCheck=3
    let blockedLightRestore=rejected{_ = try heldLighting.writeLighting(lights,baseline:original)}
    precondition(heldLighting.packets.count==1 && blockedLightRestore.contains("自动恢复失败"))
    print("PASS: hardware writes with current-map backup, stale baseline and failed-backup rejection; per-packet release checks; lost acknowledgement/readback failure rollback; held-key rollback blocked; lighting rollback preserves mappings (simulated firmware only)")
}

